
(function(){
  const launcher = document.getElementById('sbLauncher');
  const launcherDot = document.getElementById('sbLauncherDot');
  const chatWindow = document.getElementById('sbChatWindow');
  const chatClose = document.getElementById('sbChatClose');
  const chatBody = document.getElementById('sbChatBody');
  const chatInput = document.getElementById('sbChatInput');
  const chatSend = document.getElementById('sbChatSend');

  let opened = false;

  const MAIN_MENU = [
    "What is SourceQ?",
    "Explore our modules",
    "Advisory Services",
    "Send a BOM / Message",
    "Pricing"
  ];

  const BACK_LABEL = "\u2190 Back to main menu";

  // Request Type dropdown values (5 — includes the added "Plan / Pricing")
  const REQUEST_TYPES = [
    "Component / BOM Intelligence",
    "Sourcing / RFQ",
    "Advisory",
    "Plan / Pricing",
    "General Enquiry"
  ];

  // ---------- Rendering helpers ----------
  function scrollToBottom(){
    chatBody.scrollTop = chatBody.scrollHeight;
  }

  function addMessage(html, sender){
    const div = document.createElement('div');
    div.className = 'msg ' + sender;
    div.innerHTML = html;
    chatBody.appendChild(div);
    scrollToBottom();
    return div;
  }

  function addQuickReplies(options, includeBack, ctaIndexes){
    const wrap = document.createElement('div');
    wrap.className = 'quick-replies';
    options.forEach(function(opt, i){
      const btn = document.createElement('button');
      btn.className = 'qr-btn' + ((ctaIndexes && ctaIndexes.indexOf(i) !== -1) ? ' cta' : '');
      btn.textContent = opt.label || opt;
      btn.onclick = function(){
        addMessage(btn.textContent, 'user');
        wrap.remove();
        (opt.action || function(){ handleUserMessage(opt); })();
      };
      wrap.appendChild(btn);
    });
    if(includeBack){
      const back = document.createElement('button');
      back.className = 'qr-btn back';
      back.textContent = BACK_LABEL;
      back.onclick = function(){
        wrap.remove();
        showTyping(showMainMenu);
      };
      wrap.appendChild(back);
    }
    chatBody.appendChild(wrap);
    scrollToBottom();
    return wrap;
  }

  function showTyping(callback){
    const typing = document.createElement('div');
    typing.className = 'typing';
    typing.innerHTML = '<span></span><span></span><span></span>';
    chatBody.appendChild(typing);
    scrollToBottom();
    setTimeout(function(){
      typing.remove();
      callback();
    }, 550);
  }

  // ---------- Main menu ----------
  function showMainMenu(){
    addMessage("What would you like to know?", 'bot');
    addQuickReplies([
      { label: MAIN_MENU[0], action: function(){ showTyping(showDefinition); } },
      { label: MAIN_MENU[1], action: function(){ showTyping(showModulesMenu); } },
      { label: MAIN_MENU[2], action: function(){ showTyping(showAdvisoryPrompt); } },
      { label: MAIN_MENU[3], action: function(){ showTyping(function(){ showBomForm({ preset: 'General Enquiry' }); }); } },
      { label: MAIN_MENU[4], action: function(){ showTyping(showPricing); } }
    ], false);
  }

  // ---------- 1. SourceQ definition ----------
  function showDefinition(){
    addMessage(
      "<b>SourceQ</b> is an AI-powered electronic component intelligence and sourcing platform that helps hardware and procurement teams search faster, assess risk, and make better sourcing decisions." +
      "<br><br>It combines supplier, pricing, stock, lifecycle, lead-time, counterfeit, alternative, and market intelligence across millions of components to deliver practical sourcing insights.",
      'bot'
    );
    addMessage("Want us to review a part or BOM?", 'bot');
    addQuickReplies([
      { label: "Send a BOM / Message", action: function(){ showTyping(function(){ showBomForm({ preset: 'Component / BOM Intelligence' }); }); } }
    ], true, [0]);
  }

  // ---------- 2. Modules ----------
  function showModulesMenu(){
    addMessage("SourceQ runs on three modules. Tap one to learn more:", 'bot');
    addQuickReplies([
      { label: "QRadar \u2014 Search Faster", action: function(){ showTyping(showQRadar); } },
      { label: "QLens \u2014 Analyze Deeper", action: function(){ showTyping(showQLens); } },
      { label: "QProcure \u2014 Procure Smarter", action: function(){ showTyping(showQProcure); } }
    ], true);
  }

  function showQRadar(){
    addMessage(
      "<b>QRadar \u2014 Search Faster</b><br>Search millions of components across multiple supplier and market sources. QRadar helps bring stock, pricing, availability, and sourcing information into one place." +
      "<ul><li>Multi-source component search</li><li>Stock and pricing visibility</li><li>Manufacturer and supplier intelligence</li><li>BOM and multi-part search support</li></ul>",
      'bot'
    );
    addMessage("Have a part or BOM you want us to check?", 'bot');
    addQuickReplies([
      { label: "Send a BOM / Message", action: function(){ showTyping(function(){ showBomForm({ preset: 'Component / BOM Intelligence' }); }); } },
      { label: "Next: QLens", action: function(){ showTyping(showQLens); } }
    ], true, [0]);
  }

  function showQLens(){
    addMessage(
      "<b>QLens \u2014 Analyze Deeper</b><br>QLens helps teams look beyond basic part data by combining pricing, lifecycle, supply, supplier, counterfeit, alternatives, and market-event intelligence into a deeper component risk view." +
      "<ul><li>Price history and pricing trends</li><li>Lead-time and supply-risk intelligence</li><li>Lifecycle / EOL risk</li><li>Counterfeit and supplier-risk indicators</li><li>Cross references and alternatives</li><li>Recent news and event impact</li><li>AI-led component intelligence and recommendations</li></ul>",
      'bot'
    );
    addMessage("Want a QLens review for a critical component or BOM?", 'bot');
    addQuickReplies([
      { label: "Request a QLens Review", action: function(){ showTyping(function(){ showBomForm({ preset: 'Component / BOM Intelligence' }); }); } },
      { label: "Next: QProcure", action: function(){ showTyping(showQProcure); } }
    ], true, [0]);
  }

  function showQProcure(){
    addMessage(
      "<b>QProcure \u2014 Procure Smarter</b><br>QProcure connects sourcing intelligence with procurement execution. Share a requirement or BOM and our team can support supplier discovery, RFQs, quote comparison, and global sourcing execution." +
      "<ul><li>RFQ management</li><li>Supplier discovery and qualification</li><li>Quote comparison</li><li>Supplier management</li><li>Global sourcing execution</li><li>Order and shipment coordination</li></ul>",
      'bot'
    );
    addMessage("Need pricing or sourcing support?", 'bot');
    addQuickReplies([
      { label: "Send RFQ / BOM", action: function(){ showTyping(function(){ showBomForm({ preset: 'Sourcing / RFQ' }); }); } },
      { label: "See Advisory Services", action: function(){ showTyping(showAdvisoryPrompt); } }
    ], true, [0]);
  }

  // ---------- 3. Advisory Services ----------
  function showAdvisoryPrompt(){
    addMessage("Our Advisory Services team combines SourceQ intelligence with engineering and supply-chain expertise. What would you like help with?", 'bot');
    addQuickReplies([
      { label: "R&D Collaboration", action: function(){ showTyping(function(){ showAdvisoryDetail(
        "R&D Collaboration",
        "We work alongside your engineering team on component selection, alternates, BOM architecture, cost optimization, and supply resilience \u2014 from concept through DVT."
      ); }); } },
      { label: "Key BOM Forecasting", action: function(){ showTyping(function(){ showAdvisoryDetail(
        "Key BOM Forecasting",
        "Price, lead-time, lifecycle, and supply forecasting for the critical components in your BOM, helping you identify risk before it becomes a shortage or cost issue."
      ); }); } },
      { label: "Scenario & Inventory Planning", action: function(){ showTyping(function(){ showAdvisoryDetail(
        "Scenario & Inventory Planning",
        "We stress-test supply scenarios and help you model the right inventory position against demand volatility, lead-time changes, and market uncertainty."
      ); }); } },
      { label: "Supplier Concentration Modeling", action: function(){ showTyping(function(){ showAdvisoryDetail(
        "Supplier Concentration Modeling",
        "We identify single-source, geographic, manufacturer, and supplier concentration across your BOM and quantify exposure to potential supply disruption."
      ); }); } },
      { label: "News & Event Impact Modeling", action: function(){ showTyping(function(){ showAdvisoryDetail(
        "News & Event Impact Modeling",
        "We connect tariffs, export controls, geopolitical events, capacity changes, earnings commentary, shortages, and market news to the components and suppliers relevant to your BOM."
      ); }); } }
    ], true);
  }

  function showAdvisoryDetail(title, desc){
    addMessage("<b>" + title + "</b><br>" + desc, 'bot');
    addMessage("Tell us what you are trying to solve and our team will follow up.", 'bot');
    addQuickReplies([
      { label: "Talk to Advisory Team", action: function(){ showTyping(function(){ showBomForm({ preset: 'Advisory', fromAdvisory: true }); }); } },
      { label: "See other Advisory topics", action: function(){ showTyping(showAdvisoryPrompt); } }
    ], true, [0]);
  }

  // ---------- 4. BOM / Message intake ----------
  // opts: { preset: <one of REQUEST_TYPES>, fromAdvisory: bool }
  function showBomForm(opts){
    opts = opts || {};
    const preset = REQUEST_TYPES.indexOf(opts.preset) !== -1 ? opts.preset : 'General Enquiry';

    addMessage(
      opts.fromAdvisory
        ? "Sure \u2014 tell us a little more about your requirement and we'll route it to the right SourceQ team member."
        : "Send us a spot requirement, a full BOM, or simply tell us what you need. Our team will review your request and get back to you.",
      'bot'
    );

    const wrap = document.createElement('div');
    wrap.className = 'form-card';

    let typeOptionsHtml = '';
    REQUEST_TYPES.forEach(function(t){
      typeOptionsHtml += '<option value="' + t + '"' + (t === preset ? ' selected' : '') + '>' + t + '</option>';
    });

    wrap.innerHTML =
      '<p class="form-field-label">Request type</p>' +
      '<select id="sbReqType">' + typeOptionsHtml + '</select>' +
      '<div class="form-radio-row">' +
        '<label><input type="radio" name="sbReqMode" value="bom" checked> Paste a BOM</label>' +
        '<label><input type="radio" name="sbReqMode" value="message"> Just a message</label>' +
      '</div>' +
      '<textarea id="sbReqDetails" placeholder="Paste part numbers / quantities, or tell us what you need..."></textarea>' +
      '<input type="text" id="sbReqName" placeholder="Your name">' +
      '<input type="email" id="sbReqEmail" placeholder="Work email">' +
      '<input type="text" id="sbReqCompany" placeholder="Company">' +
      '<input type="text" id="sbReqPhone" placeholder="Phone / WhatsApp (optional)">' +
      '<button class="form-submit" id="sbReqSubmit">Submit</button>' +
      '<p class="form-note">We support spot buys, full BOM sourcing, component intelligence, and advisory requests. If you prefer to put an NDA in place before sharing a detailed BOM, mention it in your message.</p>';
    chatBody.appendChild(wrap);
    scrollToBottom();

    wrap.querySelector('#sbReqSubmit').onclick = function(){
      const reqType = wrap.querySelector('#sbReqType').value;
      const mode = wrap.querySelector('input[name="sbReqMode"]:checked').value;
      const details = wrap.querySelector('#sbReqDetails').value.trim();
      const name = wrap.querySelector('#sbReqName').value.trim();
      const email = wrap.querySelector('#sbReqEmail').value.trim();
      const company = wrap.querySelector('#sbReqCompany').value.trim();
      const phone = wrap.querySelector('#sbReqPhone').value.trim();

      let ok = true;
      [['sbReqDetails', details], ['sbReqName', name], ['sbReqEmail', email]].forEach(function(pair){
        const el = wrap.querySelector('#' + pair[0]);
        if(!pair[1]){ el.style.borderColor = '#ff5c5c'; ok = false; }
        else { el.style.borderColor = 'var(--glass-border)'; }
      });
      if(!ok) return;

      const submission = {
        requestType: reqType,
        mode: mode,               // 'bom' | 'message'
        details: details,
        name: name,
        email: email,
        company: company,
        phone: phone,
        submittedAt: new Date().toISOString()
      };

      // TODO(lead-submit): replace with your real submission endpoint.
      // Example:
      //   fetch('/api/spockbot-requests', {
      //     method: 'POST',
      //     headers: { 'Content-Type': 'application/json' },
      //     body: JSON.stringify(submission)
      //   });
      console.log('Spockbot request captured:', submission);

      wrap.remove();
      showTyping(function(){
        addMessage(
          "Thanks, " + name.split(' ')[0] + "! We've received your " + (mode === 'bom' ? 'BOM' : 'message') + ". Our team will review it and respond at " + email + ".",
          'bot'
        );
        addQuickReplies([], true);
      });
    };
  }

  // ---------- 5. Pricing ----------
  function showPricing(){
    addMessage(
      "SourceQ is designed to make professional component intelligence accessible \u2014 from free component search to advanced analytics, sourcing, and enterprise support. Our Pro plan starts at less than the cost of a cup of tea per day.",
      'bot'
    );

    const wrap = document.createElement('div');
    wrap.className = 'price-cards';
    wrap.innerHTML =
      '<div class="price-card">' +
        '<div class="price-card-top"><span class="price-tier">Free</span><span class="price-value">\u20B90</span></div>' +
        '<p class="price-desc">Basic component search and limited lookups per month \u2014 a simple way to explore SourceQ.</p>' +
        '<button class="qr-btn" id="sbFreeCta">Explore SourceQ</button>' +
      '</div>' +
      '<div class="price-card highlight">' +
        '<div class="price-card-top"><span class="price-tier">Pro</span><span class="price-value">Less than a cup of tea/day</span></div>' +
        '<p class="price-desc">Full QLens analytics, expanded search, lifecycle and pricing intelligence, AI-led insights, and priority sourcing support.</p>' +
        '<button class="qr-btn cta" id="sbProCta">Request Pro Access</button>' +
      '</div>' +
      '<div class="price-card">' +
        '<div class="price-card-top"><span class="price-tier">Enterprise</span><span class="price-value">Custom</span></div>' +
        '<p class="price-desc">Full QProcure access, team workflows, BOM intelligence, supplier management, dedicated advisory, and volume sourcing support.</p>' +
        '<button class="qr-btn cta" id="sbEntCta">Talk to SourceQ Team</button>' +
      '</div>';
    chatBody.appendChild(wrap);
    scrollToBottom();

    // TODO(free-tier-url): replace with your real sign-up / product URL.
    wrap.querySelector('#sbFreeCta').onclick = function(){
      window.open('https://sourceq.example.com/signup', '_blank', 'noopener');
    };
    wrap.querySelector('#sbProCta').onclick = function(){
      addMessage('Request Pro Access', 'user');
      showTyping(function(){ showBomForm({ preset: 'Plan / Pricing' }); });
    };
    wrap.querySelector('#sbEntCta').onclick = function(){
      addMessage('Talk to SourceQ Team', 'user');
      showTyping(function(){ showBomForm({ preset: 'Plan / Pricing' }); });
    };

    addQuickReplies([], true);
  }

  // ---------- Free text fallback ----------
  function handleUserMessage(text){
    const lower = (text || '').toLowerCase();
    showTyping(function(){
      if(lower.indexOf('price') !== -1 || lower.indexOf('cost') !== -1 || lower.indexOf('tier') !== -1 || lower.indexOf('plan') !== -1){
        showPricing();
      } else if(lower.indexOf('module') !== -1 || lower.indexOf('qradar') !== -1 || lower.indexOf('qlens') !== -1 || lower.indexOf('qprocure') !== -1){
        showModulesMenu();
      } else if(lower.indexOf('advisory') !== -1 || lower.indexOf('consult') !== -1){
        showAdvisoryPrompt();
      } else if(lower.indexOf('bom') !== -1 || lower.indexOf('sourc') !== -1 || lower.indexOf('quote') !== -1 || lower.indexOf('rfq') !== -1){
        showBomForm({ preset: 'General Enquiry' });
      } else if(lower.indexOf('sourceq') !== -1 || lower.indexOf('what is') !== -1){
        showDefinition();
      } else {
        // Nav rule: unmatched free text gets this exact fallback, then the
        // lead form opens immediately so the message isn't lost.
        addMessage("I can pass this to the SourceQ team. Please leave your message and contact details.", 'bot');
        showBomForm({ preset: 'General Enquiry' });
      }
    });
  }

  // ---------- Input wiring ----------
  function sendFromInput(){
    const val = chatInput.value.trim();
    if(!val) return;
    addMessage(val, 'user');
    chatInput.value = '';
    handleUserMessage(val);
  }

  chatSend.onclick = sendFromInput;
  chatInput.addEventListener('keydown', function(e){
    if(e.key === 'Enter') sendFromInput();
  });

  // ---------- Open / close ----------
  function openChat(){
    chatWindow.classList.add('open');
    launcherDot.style.display = 'none';
    if(!opened){
      opened = true;

      // Idea B: full mascot shown once, above the welcome message.
      const heroWrap = document.createElement('div');
      heroWrap.className = 'hero-wrap';
      heroWrap.innerHTML = '<img src="data:image/png;base64," alt="Spockbot">';
      chatBody.appendChild(heroWrap);
      scrollToBottom();

      showTyping(function(){
        addMessage(
          "Hi, I'm <b>Spockbot</b> \u2014 the SourceQ assistant. I can help you learn more.",
          'bot'
        );
        showMainMenu();
      });
    }
  }
  function closeChat(){
    chatWindow.classList.remove('open');
  }

  launcher.onclick = function(){
    chatWindow.classList.contains('open') ? closeChat() : openChat();
  };
  chatClose.onclick = closeChat;
})();